function draw(){
 x.fillStyle='#070910';x.fillRect(0,0,W,H);
 let horizon=H*.61;let sky=x.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#090d18');sky.addColorStop(.65,'#101627');sky.addColorStop(1,'#20243a');x.fillStyle=sky;x.fillRect(0,0,W,horizon);
 // distant city
 for(let i=0;i<18;i++){let bw=70+((i*37)%55),bx=((i*137-W*.12)% (W+180))-90,by=170+(i%4)*22,h=120+(i*53)%190;x.fillStyle=i%3?'#111425':'#17182a';x.fillRect(bx,horizon-h-bw*.1,bw,h);x.fillStyle=i%2?'#2b3150':'#1e3a4a';for(let yy=horizon-h+18;yy<horizon-12;yy+=18)for(let xx=bx+10;xx<bx+bw-5;xx+=15)if((xx+yy+i)%3<2)x.fillRect(xx,yy,4,7)}
 x.strokeStyle='rgba(103,203,230,.12)';for(let i=0;i<8;i++){let y=horizon+i*i*3;x.beginPath();x.moveTo(0,y);x.lineTo(W,y);x.stroke()}for(let i=-8;i<12;i++){x.beginPath();x.moveTo(W/2,horizon);x.lineTo(W/2+i*W*.13,H);x.stroke()}
